{
  "report": "Síntese: PETR4 mostra, até 2025-10-01, um quadro de consolidação de curto/médio prazo com viés levemente positivo, porém de baixa convicção. No longo prazo o viés continua baixista, pois o preço opera abaixo da MM200 descendente. A dinâmica recente é de faixa entre aproximadamente R$30,0 e R$32,5, com médias de curto e médio prazo próximas e quase flat, sinalizando falta de tendência definida.",
  "signal": "Neutro",
  "support_levels": [
    30,
    29,
    27.5
  ],
  "resistance_levels": [
    32.5,
    33.5,
    36
  ],
  "indicator_readings": [
    {
      "indicator": "Preço",
      "reading": "≈ R$31.3–31.6 (último pregão próximo da média móvel de curto prazo)",
      "interpretation": "Preço dentro de um range; sem ruptura clara de tendência."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$31.2",
      "interpretation": "Média curta praticamente horizontal — confirma consolidação de curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$31.4",
      "interpretation": "MM50 alinhada com MM20 — ausência de viés direcional forte no médio prazo."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$33.5",
      "interpretation": "MM200 em tendência descendente e acima do preço — viés de longo prazo baixista."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$31.5",
      "interpretation": "EMA9 levemente acima da EMA21 → pequeno impulso comprador de curtíssimo prazo, mas frágil."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$31.3",
      "interpretation": "EMA21 próxima às MMs — confirma padrão lateral."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD ligeiramente acima da linha de sinal; histograma positivo e pequeno",
      "interpretation": "Momentum virou marginalmente positivo; sinal de compra de curto prazo, porém débil."
    },
    {
      "indicator": "Bollinger (20,2σ)",
      "reading": "Bandas com largura moderada a estreita; preço perto da média/média-superior",
      "interpretation": "Volatilidade contida (squeeze relativo). Quebra de bandas com aumento de volume indicaria movimento direcional."
    },
    {
      "indicator": "RSI (14)",
      "reading": "≈ 50 (oscilações recentes entre ~40–65)",
      "interpretation": "RSI neutro — sem sobrecompra/sobrevenda; espaço para avanço ou recuo."
    },
    {
      "indicator": "Volume",
      "reading": "Volume médio com alguns picos esporádicos",
      "interpretation": "Movimentos recentes não têm confirmação volumétrica consistente — baixa convicção em rompimentos."
    }
  ]
}
